function tkcs_setting($key){$saved=get_option('tkc_editable_content',[]);$defaults=tkcs_content_defaults();return array_key_exists($key,$saved)?$saved[$key]:($defaults[$key][1]??'');}
function tkcs_local_setting($key){return tkcs_setting($key.(function_exists('tkc_lang')&&tkc_lang()==='et'?'_et':'_en'));}
function tkcs_public_email(){return sanitize_email(tkcs_setting('email'));}
add_action('admin_menu',function(){add_menu_page('Website content','Website content','manage_options','tkc-content','tkcs_content_admin','dashicons-edit-page',21);});
add_action('admin_enqueue_scripts',function($hook){if($hook==='toplevel_page_tkc-content')wp_enqueue_media();});
function tkcs_content_admin(){
 if(!current_user_can('manage_options'))return;
 echo '<div class="wrap"><h1>Website content / 网站内容</h1><p>无需修改代码：页面正文在 Pages，所有活动在 Events，公共信息在这里，导航和页脚链接在 Appearance → Menus。</p><p>English and Estonian page text is edited separately. Changes here update shared areas on every page. Newsletter subscriptions and existing event bookings are preserved.</p>';
 if(isset($_GET['saved']))echo '<div class="notice notice-success"><p>Website content saved.</p></div>';
 echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcs_content_save');echo '<input type="hidden" name="action" value="tkcs_content_save"><table class="form-table">';
 foreach(tkcs_content_defaults()as$key=>$field){list($label,$default,$type)=$field;$value=tkcs_setting($key);echo '<tr><th><label for="tkc-'.$key.'">'.esc_html($label).'</label></th><td>';
 if($type==='textarea')echo '<textarea class="large-text" rows="3" id="tkc-'.$key.'" name="content['.$key.']">'.esc_textarea($value).'</textarea>';
 elseif($type==='media'){ $id=$value?:get_theme_mod('custom_logo');echo '<input type="hidden" id="tkc-logo-id" name="content[logo_id]" value="'.absint($id).'"><button type="button" class="button" id="tkc-pick-logo">Choose logo / 选择图片</button><p id="tkc-logo-preview">'.($id?wp_get_attachment_image($id,'thumbnail'):'Current theme logo').'</p>';}
 else echo '<input class="regular-text" id="tkc-'.$key.'" type="'.esc_attr($type==='number'?'number':$type).'" '.($type==='number'?'min="1" max="24"':'').' name="content['.$key.']" value="'.esc_attr($value).'">';
 echo '</td></tr>';}
 echo '</table>';submit_button('Save website content');echo '</form><script>document.getElementById("tkc-pick-logo").onclick=function(){var frame=wp.media({title:"Choose website logo",multiple:false,library:{type:"image"}});frame.on("select",function(){var a=frame.state().get("selection").first().toJSON();document.getElementById("tkc-logo-id").value=a.id;var p=document.getElementById("tkc-logo-preview");p.textContent="";var img=document.createElement("img");img.src=a.url;img.style.maxWidth="150px";p.appendChild(img);});frame.open();};</script>';
 echo '<h2>Navigation and footer links / 导航与页脚链接</h2><p><a class="button" href="'.esc_url(admin_url('nav-menus.php')).'">Edit menus</a> — Primary menus and four footer menus are maintained using WordPress menu controls. Labels and destinations are editable.</p>';
 echo '<h2>All pages: maintenance audit / 全部页面维护入口</h2><p>普通正文、图片、资源链接及合作方信息均可在区块编辑器修改。动态组件保留短代码，使用右侧入口管理数据；不需要编辑短代码。活动页面的内容统一来自 Events。</p><table class="widefat striped"><thead><tr><th>Page</th><th>Content source / 维护方式</th><th>Actions</th></tr></thead><tbody>';
 foreach(get_posts(['lang'=>'','post_type'=>'page','post_status'=>['publish','draft','private'],'numberposts'=>-1,'suppress_filters'=>true,'orderby'=>'ID','order'=>'ASC'])as$p){
 $source=get_post_meta($p->ID,'_tkc_event_source',true);$quest=(int)get_post_meta($p->ID,'_tkcq_source',true);$notes=[];if($quest)$notes[]='<a href="'.esc_url(get_edit_post_link($quest)).'">City Surprise — edit round</a>';elseif($source)$notes[]='<a href="'.esc_url(get_edit_post_link($source)).'">Events — edit activity</a>';
 else{$notes[]='Pages — visual blocks';if((has_shortcode($p->post_content,'tkc_city_eggs')||has_shortcode($p->post_content,'tkc_city_surprise')))$notes[]='City Surprise — create and edit rounds in City Surprise';if(has_shortcode($p->post_content,'tkc_events'))$notes[]='Upcoming events: Events; display count in page settings';if(has_shortcode($p->post_content,'tkc_past_activities'))$notes[]='Past events: Events; page size above';if(has_shortcode($p->post_content,'tkc_newsletter')||has_shortcode($p->post_content,'newsletter'))$notes[]='Newsletter: labels above; subscribers in Newsletter';if(has_shortcode($p->post_content,'contact-form-7'))$notes[]='Enquiry form: Contact → Contact Forms';if(trim($p->post_content)==='')$notes=['Plugin system page — Events Manager settings'];}
 echo '<tr><td>'.esc_html($p->post_title).' ('.absint($p->ID).')</td><td>'.implode('<br>',$notes).'</td><td><a href="'.esc_url(get_edit_post_link($p->ID)).'">Edit page</a> · <a href="'.esc_url(get_permalink($p)).'">View</a></td></tr>';
 }echo '</tbody></table></div>';
}
add_action('admin_post_tkcs_content_save',function(){if(!current_user_can('manage_options'))wp_die('Not authorised.');check_admin_referer('tkcs_content_save');$input=wp_unslash($_POST['content']??[]);$saved=get_option('tkc_editable_content',[]);foreach(tkcs_content_defaults()as$key=>$f){if(!array_key_exists($key,$input))continue;$v=$input[$key];switch($f[2]){case 'email':$v=sanitize_email($v);if(!$v)wp_die('Enter a valid public email.');break;case 'url':$v=esc_url_raw($v,['http','https']);break;case 'media':$v=absint($v);if($v&&!wp_attachment_is_image($v))wp_die('Choose an image.');break;case 'number':$v=min(24,max(1,absint($v)));break;case 'textarea':$v=sanitize_textarea_field($v);break;default:$v=sanitize_text_field($v);} $saved[$key]=$v;}update_option('tkc_editable_content',$saved,false);if(!empty($saved['logo_id']))set_theme_mod('custom_logo',$saved['logo_id']);wp_safe_redirect(admin_url('admin.php?page=tkc-content&saved=1'));exit;});
// Replace shared contact identifiers at render time; preserve editable page blocks and revisions.
add_filter('render_block',function($html,$block){if(is_admin()||empty($block['blockName'])||!in_array($block['blockName'],['core/paragraph','core/list-item','core/button'],true))return $html;
 return strtr($html,['info@thekindcircle.ee'=>esc_html(tkcs_public_email()),'The Kind Circle MTÜ'=>esc_html(tkcs_setting('org_name')),'80679833'=>esc_html(tkcs_setting('registry')),'Tallinn, Estonia'=>esc_html(tkcs_setting('location')),'https://www.instagram.com/thekindcirclemtu/'=>esc_url(tkcs_setting('instagram_url'))]);
},20,2);
add_action('add_meta_boxes_page',function($post){if(has_shortcode($post->post_content,'tkc_events'))add_meta_box('tkc-list-settings','Activity list settings / 活动列表设置',function($p){wp_nonce_field('tkcs_list_settings','tkcs_list_nonce');preg_match('/\[tkc_events\b([^\]]*)\]/',$p->post_content,$m);$a=shortcode_parse_atts($m[1]??'');echo '<p><label>Upcoming activities shown<br><input name="tkc_future_limit" type="number" min="1" max="50" value="'.absint($a['limit']??12).'"></label></p><p>Activity content is maintained in Events. Historical page size is set in Website content.</p>';},'page','side');});
add_filter('wp_insert_post_data',function($data,$postarr){if(($data['post_type']??'')!=='page'||empty($_POST['tkcs_list_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tkcs_list_nonce'])),'tkcs_list_settings')||!current_user_can('edit_post',$postarr['ID']??0))return $data;$limit=min(50,max(1,absint($_POST['tkc_future_limit']??12)));$data['post_content']=preg_replace_callback('/\[tkc_events\b([^\]]*)\]/',function($m)use($limit){$attrs=preg_replace('/\s*limit\s*=\s*(?:"[^"]*"|\x27[^\x27]*\x27|[^\s]+)/','',$m[1]);return '[tkc_events'.$attrs.' limit="'.$limit.'"]';},$data['post_content']);return $data;},20,2);
function tkcs_footer_menu($column,$lang){$menu=wp_get_nav_menu_object('TKC Footer '.$column.' '.strtoupper($lang));if(!$menu)return;echo '<ul>';foreach(wp_get_nav_menu_items($menu,['suppress_filters'=>true])?:[]as$i)echo '<li><a href="'.esc_url($i->object==='page'?get_permalink($i->object_id):$i->url).'">'.esc_html($i->title).'</a></li>';echo '</ul>';}
add_action('admin_init',function(){if(!current_user_can('manage_options')||get_option('tkc_editable_menus_ready'))return;$map=get_option('tkc_page_map',[]);foreach(['en','et']as$lang)foreach([1=>['activities'=>['Activities','Tegevused'],'get-involved'=>['Get involved','Löö kaasa'],'support-us'=>['Support us','Toeta meid'],'partnerships'=>['Partnerships','Koostöö']],2=>['about-us'=>['About us','Meist'],'resources'=>['Community resources','Kogukonna ressursid'],'newsletter'=>['Newsletter','Uudiskiri'],'contact'=>['Contact','Kontakt']]]as$col=>$items){$name='TKC Footer '.$col.' '.strtoupper($lang);$menu=wp_get_nav_menu_object($name);if($menu)continue;$id=wp_create_nav_menu($name);if(is_wp_error($id))return;if(function_exists('pll_set_term_language'))pll_set_term_language($id,$lang);foreach($items as$key=>$labels){$pid=$map[$key][$lang]??0;if(!$pid)continue;wp_update_nav_menu_item($id,0,['menu-item-title'=>$labels[$lang==='et'?1:0],'menu-item-object-id'=>$pid,'menu-item-object'=>'page','menu-item-type'=>'post_type','menu-item-status'=>'publish']);}}update_option('tkc_editable_menus_ready',1,false);});
// Plain-text form labels and messages, without exposing Contact Form 7 markup.
add_action('admin_menu',function(){add_submenu_page('tkc-content','Form text','Form text / 表单文案','manage_options','tkc-form-text','tkcs_form_text_admin');});
function tkcs_form_labels($markup){preg_match_all('/<label>([^<\[]*?)\s*\[(?:text|email|textarea|select|file)\*?\s+([\w-]+)/u',$markup,$m,PREG_SET_ORDER);$out=[];foreach($m as$x)if($x[2]!=='tkc-website')$out[$x[2]]=trim($x[1]);return $out;}
function tkcs_form_text_admin(){if(!current_user_can('manage_options')||!class_exists('WPCF7_ContactForm'))return;echo '<div class="wrap"><h1>Form text / 表单文案</h1><p>选择表单后修改显示标签、发送按钮及反馈提示。字段类型、必填规则、邮件路由和现有提交记录保持不变。</p>';
 $forms=WPCF7_ContactForm::find(['posts_per_page'=>-1,'lang'=>'']);$id=absint($_GET['form_id']??0);echo '<ul>';foreach($forms as$f)echo '<li><a href="'.esc_url(add_query_arg(['page'=>'tkc-form-text','form_id'=>$f->id()],admin_url('admin.php'))).'">'.esc_html($f->title()).'</a></li>';echo '</ul>';
 $f=$id?WPCF7_ContactForm::get_instance($id):null;if(!$f){echo '</div>';return;}echo '<h2>'.esc_html($f->title()).'</h2>';if(isset($_GET['saved']))echo '<p>Form text saved.</p>';echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'">';wp_nonce_field('tkcs_form_text_'.$id);$markup=$f->prop('form');echo '<input type="hidden" name="action" value="tkcs_form_text"><input type="hidden" name="form_id" value="'.$id.'"><input type="hidden" name="form_version" value="'.esc_attr(hash('sha256',$markup)).'"><table class="form-table">';foreach(tkcs_form_labels($markup)as$key=>$label)echo '<tr><th><label for="label-'.$key.'">'.esc_html($key).'</label></th><td><input class="regular-text" id="label-'.$key.'" name="labels['.$key.']" value="'.esc_attr($label).'"></td></tr>';
 foreach(tkcs_form_selects($markup)as$key=>$choices)echo '<tr><th><label for="choices-'.$key.'">'.esc_html($key).' options</label></th><td><textarea class="large-text" rows="6" id="choices-'.$key.'" name="choices['.$key.']">'.esc_textarea(implode("\n",$choices)).'</textarea><p>One option per line. Keep the first placeholder line when present.</p></td></tr>';
 if(preg_match('/\[submit\s+"([^"]*)"\]/u',$markup,$m))echo '<tr><th><label for="submit-label">Submit button</label></th><td><input class="regular-text" id="submit-label" name="submit_label" value="'.esc_attr($m[1]).'"></td></tr>';
 foreach($f->prop('messages')as$key=>$value)echo '<tr><th><label for="message-'.$key.'">'.esc_html(ucwords(str_replace('_',' ',$key))).'</label></th><td><input class="large-text" id="message-'.$key.'" name="messages['.esc_attr($key).']" value="'.esc_attr($value).'"></td></tr>';
 echo '</table>';submit_button('Save form text');echo '</form></div>';}
add_action('admin_post_tkcs_form_text',function(){if(!current_user_can('manage_options')||!class_exists('WPCF7_ContactForm'))wp_die('Not authorised.');$id=absint($_POST['form_id']??0);check_admin_referer('tkcs_form_text_'.$id);$f=WPCF7_ContactForm::get_instance($id);if(!$f)wp_die('Form unavailable.');$markup=$f->prop('form');if(!hash_equals(hash('sha256',$markup),sanitize_text_field(wp_unslash($_POST['form_version']??''))))wp_die('The form changed. Reload before saving.');$labels=wp_unslash($_POST['labels']??[]);$markup=preg_replace_callback('/<label>([^<\[]*?)\s*\[((?:text|email|textarea|select|file)\*?)\s+([\w-]+)/u',function($m)use($labels){if($m[3]==='tkc-website'||!isset($labels[$m[3]]))return $m[0];return '<label>'.esc_html(sanitize_text_field($labels[$m[3]])).' ['.$m[2].' '.$m[3];},$markup);
 $choices=wp_unslash($_POST['choices']??[]);$markup=preg_replace_callback('/\[(select\*?\s+([\w-]+)[^"\]]*)((?:"[^"]*"\s*)+)\]/u',function($m)use($choices){if(!isset($choices[$m[2]]))return $m[0];$values=array_filter(array_map('sanitize_text_field',preg_split('/\R/u',$choices[$m[2]])),function($v){return $v!=='';});if(!$values)return $m[0];return '['.$m[1].implode(' ',array_map(function($v){return '"'.str_replace(['"',']','['],['','',''],$v).'"';},$values)).']';},$markup);
 if(isset($_POST['submit_label'])){$label=sanitize_text_field(wp_unslash($_POST['submit_label']));$markup=preg_replace('/\[submit\s+"[^"]*"\]/u','[submit "'.esc_attr($label).'"]',$markup);}$messages=$f->prop('messages');$new=wp_unslash($_POST['messages']??[]);foreach($messages as$key=>$value)if(isset($new[$key]))$messages[$key]=sanitize_text_field($new[$key]);$f->set_properties(['form'=>$markup,'messages'=>$messages]);$f->save();wp_safe_redirect(add_query_arg(['page'=>'tkc-form-text','form_id'=>$id,'saved'=>1],admin_url('admin.php')));exit;});
// Keep the plugin's legacy Events landing URL useful alongside the bilingual Activities pages.
add_action('template_redirect',function(){if(is_admin()||wp_doing_ajax())return;$id=(int)get_option('dbem_events_page');if(!$id){$p=get_page_by_path('events');$id=$p?$p->ID:0;}if(!$id)return;$path=untrailingslashit(wp_parse_url(get_permalink($id),PHP_URL_PATH));$requested=untrailingslashit(wp_parse_url(wp_unslash($_SERVER['REQUEST_URI']??''),PHP_URL_PATH));if(!$path||$path!==$requested)return;$map=get_option('tkc_page_map',[]);$lang=function_exists('tkc_lang')?tkc_lang():'en';$target=$map['activities'][$lang]??0;if($target&&get_post_status($target)==='publish'){wp_safe_redirect(get_permalink($target),301);exit;}});
add_action('add_meta_boxes_page',function(){add_meta_box('tkc-page-description','Search description / 页面搜索摘要',function($p){wp_nonce_field('tkcs_description','tkcs_description_nonce');echo '<p>页面的搜索摘要，可直接输入普通文字。</p><textarea name="tkc_description" rows="4" style="width:100%">'.esc_textarea(get_post_meta($p->ID,'tkc_description',true)).'</textarea>';},'page','side');});
add_action('save_post_page',function($id){if(empty($_POST['tkcs_description_nonce'])||!wp_verify_nonce(sanitize_text_field(wp_unslash($_POST['tkcs_description_nonce'])),'tkcs_description')||!current_user_can('edit_post',$id)||wp_is_post_revision($id))return;update_post_meta($id,'tkc_description',sanitize_textarea_field(wp_unslash($_POST['tkc_description']??'')));});
function tkcs_form_selects($markup){preg_match_all('/\[(select\*?\s+([\w-]+)[^"\]]*)((?:"[^"]*"\s*)+)\]/u',$markup,$m,PREG_SET_ORDER);$out=[];foreach($m as$x){preg_match_all('/"([^"]*)"/u',$x[3],$choices);$out[$x[2]]=$choices[1];}return $out;}

function tkcs_social_icons(){
    $links=['instagram'=>'Instagram','facebook'=>'Facebook','linkedin'=>'LinkedIn','whatsapp'=>'WhatsApp'];$items='';
    foreach($links as$service=>$label){$url=tkcs_setting($service.'_url');if(!$url)continue;
        $items.=render_block(['blockName'=>'core/social-link','attrs'=>['url'=>esc_url_raw($url),'service'=>$service,'label'=>$label],'innerBlocks'=>[],'innerHTML'=>'','innerContent'=>[]]);
    }
    if(!$items)return '';
    return '<nav aria-label="'.esc_attr(function_exists('tkc_lang')&&tkc_lang()==='et'?'Sotsiaalmeedia':'Social media').'" class="tkc-social-nav"><ul class="wp-block-social-links is-style-logos-only tkc-social-links">'.$items.'</ul></nav>';
}
